const r = await tools.exec_command({cmd:"python - <<'PY'
import csv, collections
p='dataset/hospital_compensation_registry.csv'
rows=list(csv.DictReader(open(p)))
by={r['patient_id']:r for r in rows}
special={'PAT_006','PAT_265','PAT_033','PAT_078','PAT_065','PAT_011'}
print('rows',len(rows),'unique patients',len(by),'contacts represented',sum(r['emergency_contact_patient_id'] in by for r in rows))
print('\nSpecial nodes and their incoming references:')
for x in sorted(special):
    print('\n',x, by.get(x))
    for r in rows:
        if r['emergency_contact_patient_id']==x:
            print(' <-',r)
print('\nTop contact in-degrees:')
counts=collections.Counter(r['emergency_contact_patient_id'] for r in rows)
for x,n in counts.most_common(25):
    rr=by.get(x)
    print(x,n, rr['compensation_reason'] if rr else '<not in registry rows>', rr['coverage_status'] if rr else '')
print('\nMutual emergency-contact pairs:')
for r in rows:
    c=r['emergency_contact_patient_id']
    if c in by and by[c]['emergency_contact_patient_id']==r['patient_id'] and r['patient_id']<c:
        print(r['patient_id'],c, '|',r['compensation_reason'],'|',by[c]['compensation_reason'])
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:30000});
text(r.output);

